<template>
	<view class="page">
		<view class="header">
			<text class="title">{{ metricName }}</text>
			<view class="tabs">
				<view :class="['tab', currentRange==='day'?'active':'']" @click="switchRange('day')">日</view>
				<view :class="['tab', currentRange==='week'?'active':'']" @click="switchRange('week')">周</view>
				<view :class="['tab', currentRange==='month'?'active':'']" @click="switchRange('month')">月</view>
				<view :class="['tab', currentRange==='year'?'active':'']" @click="switchRange('year')">年</view>
			</view>
		</view>

		<view class="chart-wrap">
			<qiun-data-charts type="line" :opts="chartOpts" :chartData="chartData" />
		</view>

		<view class="table-wrap">
			<view class="row header">
				<text class="cell idx">#</text>
				<text class="cell time">时间</text>
				<text class="cell value">数值（{{ unit }}）</text>
				<text class="cell device">设备</text>
			</view>
			<view class="row" v-for="(item, idx) in tableRows" :key="idx">
				<text class="cell idx">{{ idx + 1 }}</text>
				<text class="cell time">{{ item.timeStr }}</text>
				<text class="cell value">{{ item.value }}</text>
				<text class="cell device">{{ item.device }}</text>
			</view>
		</view>
	</view>
</template>

<script>
export default {
	data(){
		return {
			userId: '',
			metric: 'heart_rate',
			metricName: '心率',
			unit: 'bpm',
			currentRange: 'year',
			chartData: { categories: [], series: [{ name: '', data: [] }] },
			chartOpts: { legend: { show: false } },
			tableRows: []
		}
	},
	onLoad(query){
		this.metric = query.metric || 'heart_rate'
		this.userId = query.user_id || ''
		const map = {
			heart_rate: { name: '心率', unit: 'bpm' },
			temperature: { name: '体温', unit: '℃' },
			blood_oxygen: { name: '血氧饱和度', unit: '%' }
		}
		const m = map[this.metric] || map.heart_rate
		this.metricName = m.name
		this.unit = m.unit
		uni.setNavigationBarTitle({ title: `${this.metricName}趋势` })
		this.fetchData()
	},
	methods: {
		switchRange(r){
			this.currentRange = r
			this.fetchData()
		},
		toTimeRange(){
			switch(this.currentRange){
				case 'day': return '-1d'
				case 'week': return '-7d'
				case 'month': return '-30d'
				case 'year': return '-365d'
				default: return '-30d'
			}
		},
		async fetchData(){
			try{
				const res = await uni.request({
					url: 'http://localhost:3000/api/health/user',
					method: 'POST',
					data: { user_id: this.userId, time_range: this.toTimeRange(), fields: this.metric },
					timeout: 10000
				})
				const data = res[1].data || {}
				let arr = []
				if (data.status==='success' && data.user_data){
					arr = Array.isArray(data.user_data) ? data.user_data : [data.user_data]
					arr = arr.filter(it=> (it.field||it.filed)===this.metric)
					if (arr.length>0 && (arr[0].time||arr[0].timestamp||arr[0].datetime||arr[0].record_time)){
						arr.sort((a,b)=>new Date(a.time||a.timestamp||a.datetime||a.record_time)-new Date(b.time||b.timestamp||b.datetime||b.record_time))
					}
				}
				this.buildChart(arr)
			}catch(e){
				this.chartData={categories:[],series:[{name:'',data:[]}]} 
				this.tableRows=[]
			}
		},
		buildChart(arr){
			const labels = []
			const values = []
			const rows = []
			arr.forEach(it=>{
				const ts = it.time||it.timestamp||it.datetime||it.record_time
				const timeStr = ts ? new Date(ts).toLocaleDateString('zh-CN') : ''
				labels.push(timeStr)
				values.push(Number(it.value))
				rows.push({ timeStr: ts ? new Date(ts).toLocaleString('zh-CN'): '-', value: Number(it.value).toFixed(2), device: `${it.device_id||'-'}(${it.device_name||'-'})` })
			})
			this.chartData = { categories: labels, series: [{ name: this.metricName, data: values }] }
			this.tableRows = rows
		}
	}
}
</script>

<style>
	.page { padding: 24rpx; background: #FFFFFF; }
	.header { display: flex; align-items: center; justify-content: space-between; }
	.title { font-size: 36rpx; font-weight: 700; color: #111; }
	.tabs { display: flex; }
	.tab { padding: 10rpx 24rpx; margin-left: 12rpx; border-radius: 999rpx; background: #F3F4F6; color: #333; }
	.active { background: #111827; color: #FFFFFF; }
	.chart-wrap { margin-top: 24rpx; }
	.table-wrap { margin-top: 24rpx; }
	.row { display: flex; padding: 10rpx 0; border-bottom: 1rpx solid #eee; }
	.header.row { font-weight: 700; color: #666; }
	.cell { font-size: 26rpx; color: #333; }
	.idx { width: 80rpx; }
	.time { flex: 1; }
	.value { width: 220rpx; text-align: right; }
	.device { width: 300rpx; text-align: right; }
</style>

